/* STM32CubeU5 HAL RTC test.
 *
 * Unmodified HAL. The RTC is clocked by the LSE (32.768 kHz) with the default prescalers
 * (127, 255) giving 1 Hz, configured as generated by STM32CubeMX (backup domain access, LSE on,
 * RTC clock selection, HAL_RTC_Init, HAL_RTC_SetTime, HAL_RTC_SetDate). Alarm A is set to the
 * next minute and the wake-up timer fires every second from ck_spre. The main loop waits for
 * interrupts and stores the calendar; the robot test reads the global variables. */

#include "clock_160mhz.h"

RTC_HandleTypeDef hrtc;

volatile uint32_t step;
volatile uint32_t failedStep;
volatile uint32_t wakeupCount;
volatile uint32_t alarmCount;
volatile uint32_t alarmMinute;
volatile uint32_t hours;
volatile uint32_t minutes;
volatile uint32_t seconds;
volatile uint32_t year;
volatile uint32_t month;
volatile uint32_t day;
volatile uint32_t weekDay;

void SysTick_Handler(void)
{
    HAL_IncTick();
}

void RTC_IRQHandler(void)
{
    HAL_RTC_AlarmIRQHandler(&hrtc);
    HAL_RTCEx_WakeUpTimerIRQHandler(&hrtc);
}

void HAL_RTC_AlarmAEventCallback(RTC_HandleTypeDef *rtc)
{
    RTC_TimeTypeDef time = {0};
    RTC_DateTypeDef date = {0};

    HAL_RTC_GetTime(rtc, &time, RTC_FORMAT_BIN);
    HAL_RTC_GetDate(rtc, &date, RTC_FORMAT_BIN);
    alarmMinute = time.Minutes;
    alarmCount++;
}

void HAL_RTCEx_WakeUpTimerEventCallback(RTC_HandleTypeDef *rtc)
{
    (void)rtc;
    wakeupCount++;
}

static void check(HAL_StatusTypeDef status, uint32_t at)
{
    step = at;
    if (status != HAL_OK)
    {
        failedStep = at;
        for (;;)
        {
        }
    }
}

void HAL_RTC_MspInit(RTC_HandleTypeDef *rtc)
{
    RCC_PeriphCLKInitTypeDef clock = {0};

    if (rtc->Instance != RTC)
    {
        return;
    }
    clock.PeriphClockSelection = RCC_PERIPHCLK_RTC;
    clock.RTCClockSelection = RCC_RTCCLKSOURCE_LSE;
    check(HAL_RCCEx_PeriphCLKConfig(&clock), 100);
    __HAL_RCC_RTC_ENABLE();
    __HAL_RCC_RTCAPB_CLK_ENABLE();
    HAL_NVIC_SetPriority(RTC_IRQn, 0, 0);
    HAL_NVIC_EnableIRQ(RTC_IRQn);
}

static void lseConfig(void)
{
    RCC_OscInitTypeDef oscillator = {0};

    HAL_PWR_EnableBkUpAccess();
    __HAL_RCC_LSEDRIVE_CONFIG(RCC_LSEDRIVE_LOW);
    oscillator.OscillatorType = RCC_OSCILLATORTYPE_LSE;
    oscillator.LSEState = RCC_LSE_ON;
    oscillator.PLL.PLLState = RCC_PLL_NONE;
    check(HAL_RCC_OscConfig(&oscillator), 3);
}

int main(void)
{
    check(HAL_Init(), 1);
    check(SystemClockConfig160MHz(), 2);
    __HAL_RCC_PWR_CLK_ENABLE();
    lseConfig();

    hrtc.Instance = RTC;
    hrtc.Init.HourFormat = RTC_HOURFORMAT_24;
    hrtc.Init.AsynchPrediv = 127;
    hrtc.Init.SynchPrediv = 255;
    hrtc.Init.OutPut = RTC_OUTPUT_DISABLE;
    hrtc.Init.OutPutRemap = RTC_OUTPUT_REMAP_NONE;
    hrtc.Init.OutPutPolarity = RTC_OUTPUT_POLARITY_HIGH;
    hrtc.Init.OutPutType = RTC_OUTPUT_TYPE_OPENDRAIN;
    hrtc.Init.OutPutPullUp = RTC_OUTPUT_PULLUP_NONE;
    hrtc.Init.BinMode = RTC_BINARY_NONE;
    check(HAL_RTC_Init(&hrtc), 4);

    RTC_TimeTypeDef time = {0};
    time.Hours = 12;
    time.Minutes = 34;
    time.Seconds = 56;
    time.DayLightSaving = RTC_DAYLIGHTSAVING_NONE;
    time.StoreOperation = RTC_STOREOPERATION_RESET;
    check(HAL_RTC_SetTime(&hrtc, &time, RTC_FORMAT_BIN), 5);

    RTC_DateTypeDef date = {0};
    date.WeekDay = RTC_WEEKDAY_FRIDAY;
    date.Month = RTC_MONTH_OCTOBER;
    date.Date = 23;
    date.Year = 26;
    check(HAL_RTC_SetDate(&hrtc, &date, RTC_FORMAT_BIN), 6);

    /* Alarm A at 12:35:00, every day. */
    RTC_AlarmTypeDef alarm = {0};
    alarm.AlarmTime.Hours = 12;
    alarm.AlarmTime.Minutes = 35;
    alarm.AlarmTime.Seconds = 0;
    alarm.AlarmMask = RTC_ALARMMASK_DATEWEEKDAY;
    alarm.AlarmSubSecondMask = RTC_ALARMSUBSECONDMASK_ALL;
    alarm.AlarmDateWeekDaySel = RTC_ALARMDATEWEEKDAYSEL_DATE;
    alarm.AlarmDateWeekDay = 1;
    alarm.Alarm = RTC_ALARM_A;
    check(HAL_RTC_SetAlarm_IT(&hrtc, &alarm, RTC_FORMAT_BIN), 7);

    /* Wake-up timer from ck_spre (1 Hz): WUT = 0 gives one event per second. */
    check(HAL_RTCEx_SetWakeUpTimer_IT(&hrtc, 0, RTC_WAKEUPCLOCK_CK_SPRE_16BITS, 0), 8);

    step = 9;
    for (;;)
    {
        __WFI();
        HAL_RTC_GetTime(&hrtc, &time, RTC_FORMAT_BIN);
        HAL_RTC_GetDate(&hrtc, &date, RTC_FORMAT_BIN);
        hours = time.Hours;
        minutes = time.Minutes;
        seconds = time.Seconds;
        year = date.Year;
        month = date.Month;
        day = date.Date;
        weekDay = date.WeekDay;
    }
}
